"""Translates VHDL entities of the 63F09 design to C.

usage: gen.py <vhdl dir> <output dir> [entity ...]
"""

import os
import sys

import frontend
from cgen import Binding, E, Out, Translator, cid, mask
from vtypes import Bit, Enum, Int, Unsupported, Vec, type_of, unsupported
from pyGHDL.libghdl.vhdl import nodes, nodes_meta

K = nodes.Iir_Kind
F = nodes_meta.fields

BANNER = """/*
 * Generated by tools/vhdl2c from the VHDL entity %s : do not edit.
 * See docs/GENERATION.md.
 */
"""


def ctype_decl(ct):
    if ct.kind == "int":
        return "int64_t"
    if ct.kind == "enum":
        return "uint32_t"
    return "uint64_t"


class EntityGen(Translator):
    def __init__(self, entity, arch):
        super().__init__()
        self.entity, self.arch = entity, arch
        self.name = cid(frontend.ident(entity))
        self.generics, self.ports, self.signals = [], [], []
        self.procs = []                 # (function name, body text, sensitivity code list)
        self.vars = []                  # struct fields for the process variables

    # ------------------------------------------------------------------ declarations

    def declare(self):
        g = nodes.Get_Generic_Chain(self.entity)
        while g:
            ct = type_of(nodes.Get_Type(g))
            name = cid(frontend.ident(g))
            self.generics.append((name, ct))
            self.bindings[g] = Binding("var", "self->g_" + name, ct)
            g = nodes.Get_Chain(g)
        p = nodes.Get_Port_Chain(self.entity)
        while p:
            ct = type_of(nodes.Get_Type(p))
            name = cid(frontend.ident(p))
            self.ports.append((name, ct, nodes.Get_Mode(p)))
            self.bindings[p] = Binding("sigptr", "self->p_" + name, ct)
            p = nodes.Get_Chain(p)
        d = nodes.Get_Declaration_Chain(self.arch)
        while d:
            k = nodes.Get_Kind(d)
            if k == K.Signal_Declaration:
                ct = type_of(nodes.Get_Type(d))
                name = cid(frontend.ident(d))
                init = nodes.Get_Default_Value(d)
                self.signals.append((name, ct, init))
                self.bindings[d] = Binding("sig", "self->s_" + name, ct)
            elif k == K.Constant_Declaration:
                ct = type_of(nodes.Get_Type(d))
                e = self.expr(nodes.Get_Default_Value(d))
                self.bindings[d] = Binding("const", "(" + e.code + ")", ct)
            elif k in (K.Type_Declaration, K.Subtype_Declaration, K.Anonymous_Type_Declaration,
                       K.Attribute_Declaration, K.Attribute_Specification, K.Use_Clause):
                pass
            else:
                raise unsupported(d, "architecture declaration")
            d = nodes.Get_Chain(d)

    # ------------------------------------------------------------------ concurrent statements

    def concurrent(self):
        s = nodes.Get_Concurrent_Statement_Chain(self.arch)
        while s:
            k = nodes.Get_Kind(s)
            if k == K.Sensitized_Process_Statement:
                self.process(s)
            else:
                raise unsupported(s, "concurrent statement")
            s = nodes.Get_Chain(s)

    def process(self, p):
        index = len(self.procs)
        fname = "%s_p%d" % (self.name, index)
        saved = self.out
        self.out = Out()
        o = self.out
        o.open("static void %s(void *inst)" % fname)
        o.line("%s *self = inst;" % self.name)
        d = nodes.Get_Declaration_Chain(p)
        if d:
            raise unsupported(d, "process declaration")
        self.stmts(nodes.Get_Sequential_Statement_Chain(p))
        o.close()
        sens = []
        for item in frontend.list_elements(nodes.Get_Sensitivity_List(p)):
            ptr = self.sigptr(item)[0]
            if ptr not in sens:
                sens.append(ptr)
        self.procs.append((fname, o.text(), sens))
        self.out = saved

    # ------------------------------------------------------------------ output

    def generate(self):
        self.declare()
        self.concurrent()
        return self.header(), self.source()

    def params(self):
        out = ["vs_kernel *k", "%s *self" % self.name]
        out += ["%s g_%s" % (ctype_decl(ct), n) for n, ct in self.generics]
        out += ["vs_sig *%s" % n for n, ct, mode in self.ports]
        return ", ".join(out)

    def header(self):
        guard = "GEN_%s_H" % self.name.upper()
        o = Out()
        o.line(BANNER % frontend.ident(self.entity))
        o.line("#ifndef %s" % guard)
        o.line("#define %s" % guard)
        o.line()
        o.line('#include "vsim.h"')
        o.line()
        o.open("typedef struct %s" % self.name)
        for n, ct in self.generics:
            o.line("%s g_%s;" % (ctype_decl(ct), n))
        for n, ct, mode in self.ports:
            o.line("vs_sig *p_%s;" % n)
        for n, ct, init in self.signals:
            o.line("vs_sig s_%s;" % n)
        o.close(" %s;" % self.name)
        o.line()
        o.line("void %s_create(%s);" % (self.name, self.params()))
        o.line()
        o.line("#endif")
        return o.text()

    def source(self):
        o = Out()
        o.line(BANNER % frontend.ident(self.entity))
        o.line('#include "%s.h"' % self.name)
        o.line()
        for fname, body, sens in self.procs:
            o.lines.extend(body.rstrip("\n").split("\n"))
            o.line()
        o.open("void %s_create(%s)" % (self.name, self.params()))
        for n, ct in self.generics:
            o.line("self->g_%s = g_%s;" % (n, n))
        for n, ct, mode in self.ports:
            o.line("self->p_%s = %s;" % (n, n))
        for n, ct, init in self.signals:
            val = self.expr(init).code if init else self.default(ct)
            o.line("vs_register_signal(k, &self->s_%s, %s);" % (n, val))
        for fname, body, sens in self.procs:
            if sens:
                o.open("")
                o.line("vs_sig *sens[%d];" % len(sens))
                for i, s in enumerate(sens):
                    o.line("sens[%d] = %s;" % (i, s))
                o.line("vs_register_process(k, %s, self, sens, %d);" % (fname, len(sens)))
                o.close()
            else:
                o.line("vs_register_process(k, %s, self, NULL, 0);" % fname)
        o.close()
        return o.text()

    def default(self, ct):
        return "0"


def find_unit(design_files, name, kind):
    for df in design_files:
        for unit in frontend.units(df):
            lu = nodes.Get_Library_Unit(unit)
            if nodes.Get_Kind(lu) == kind and frontend.ident(lu).lower() == name.lower():
                return lu
    return 0


# Entities written by hand (they wrap vendor primitives) : never translated.
HAND_WRITTEN = ("ram_61f64x1", "ram_61f512", "ram_61f32x64", "rom_27f512")


def all_entities(dfs):
    for df in dfs:
        for unit in frontend.units(df):
            lu = nodes.Get_Library_Unit(unit)
            if nodes.Get_Kind(lu) == K.Entity_Declaration:
                name = frontend.ident(lu).lower()
                lib = frontend.ident(nodes.Get_Library(nodes.Get_Design_File(unit))) if False else ""
                if name not in HAND_WRITTEN and name not in UNISIM:
                    yield name


UNISIM = ("bufg", "bufhce", "iobuf", "obuf", "plle2_base", "ramb18e1", "ramb36e1")


def main(argv):
    vhdl_dir, out_dir = argv[1], argv[2]
    names = argv[3:]
    frontend.init()
    here = os.path.dirname(os.path.abspath(__file__))
    dfs = frontend.load_project(vhdl_dir, os.path.join(here, "sources.list"))
    if names == ["all"]:
        names = list(all_entities(dfs))
    os.makedirs(out_dir, exist_ok=True)
    failed = 0
    for name in names:
        entity = find_unit(dfs, name, K.Entity_Declaration)
        if not entity:
            sys.exit("no entity " + name)
        arch = None
        for df in dfs:
            for unit in frontend.units(df):
                lu = nodes.Get_Library_Unit(unit)
                if nodes.Get_Kind(lu) == K.Architecture_Body and nodes.Get_Entity_Name(lu) and \
                        nodes.Get_Named_Entity(nodes.Get_Entity_Name(lu)) == entity:
                    arch = lu
        try:
            h, c = EntityGen(entity, arch).generate()
        except Unsupported as e:
            print("%s : UNSUPPORTED %s" % (name, e))
            failed += 1
            continue
        base = cid(frontend.ident(entity))
        open(os.path.join(out_dir, base + ".h"), "w").write(h)
        open(os.path.join(out_dir, base + ".c"), "w").write(c)
        print("%s : generated %s.c/.h" % (name, base))
    return 1 if failed else 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))
